"""The arms of the EXP-B-004 dev search, generated by fixed rules so the log can be re-derived.

L1 has a budget of 48 configurations, filled in three stages (prioritisation written in the log header
before any run): all four forms x six weights at k = 0.5 (24); k = 0.8 for the two best forms (12);
the gated tau = 0.4 and capped C in {1, 3} variants (12). L2 is the best two L1 forms x three KBs (6).
L3 is sex, age_mean, age_any and onset x three weights on the L1+L2 winner (12).
"""

from dataclasses import replace

from diagnostic_ar_training.eval import dev_search
from diagnostic_ar_training.eval.dev_search import Arm
from diagnostic_ar_training.rerank.config import RerankConfig

KB_L1 = "kb-v6"
WEIGHTS = (0.5, 0.75, 1.0, 1.5, 2.0, 3.0)
FORMS = ("llr", "gated", "capped", "propagated")
DEFAULT_TAU, DEFAULT_CAP = 0.2, 2.0
BUDGET = {"L1": 48, "L2": 6, "L3": 12, "L4": 6}
L2_KBS = ("kb-v6", "kb-v8", "kb-v7")
L3_WEIGHTS = (0.5, 1.0, 2.0)
L3_GROUPS = {
    "sex": ("sex_prior", "sex_restricted"),
    "age_mean": ("age_mean",),
    "age_any": ("age_any",),
    "onset": ("onset",),
}


def neg_arm(
    form: str, k: float, w: float, kb: str = KB_L1, tau: float | None = None, cap: float | None = None
) -> Arm:
    if form == "gated":
        tau = DEFAULT_TAU if tau is None else tau
    if form == "capped":
        cap = DEFAULT_CAP if cap is None else cap
    config = RerankConfig(kb, form, k, tau, cap, weights={"neg_llr": w})
    param = f":tau{tau:g}" if tau is not None else (f":cap{cap:g}" if cap is not None else "")
    return Arm(f"L1:{form}{param}:k{k:g}:w{w:g}", "L1", config)


def l1_stage_a() -> list[Arm]:
    return [neg_arm(form, 0.5, w) for form in FORMS for w in WEIGHTS]


def form_scores(rows: list[dict], arms: dict[str, Arm]) -> list[tuple[str, dict]]:
    """Forms best first: those with a feasible arm by their best feasible Δ, then the rest by best Δ."""
    best: dict[str, dict] = {}
    for form in FORMS:
        mine = [r for r in rows if arms[r["arm_id"]].config.neg_form == form]
        if not mine:
            continue
        ok = [r for r in mine if dev_search.feasible(r)]
        pool = ok or mine
        top = max(r["delta"] for r in pool)
        near = [r for r in pool if r["delta"] >= top - dev_search.TIE]
        best[form] = {
            **min(near, key=lambda r: (dev_search.complexity(arms[r["arm_id"]]), r["arm_id"])),
            "has_feasible": bool(ok),
        }
    return sorted(
        best.items(), key=lambda kv: (not kv[1]["has_feasible"], -kv[1]["delta"], FORM_ORDER[kv[0]])
    )


FORM_ORDER = {f: i for i, f in enumerate(FORMS)}


def l1_stage_b(rows_a: list[dict], arms: dict[str, Arm]) -> list[Arm]:
    """k = 0.8 at every weight for the two best forms of stage a (default tau and cap)."""
    top = [form for form, _ in form_scores(rows_a, arms)[:2]]
    return [neg_arm(form, 0.8, w) for form in top for w in WEIGHTS]


def l1_stage_c() -> list[Arm]:
    gated = [neg_arm("gated", 0.5, w, tau=0.4) for w in WEIGHTS]
    capped = [neg_arm("capped", 0.5, w, cap=c) for c in (1.0, 3.0) for w in (1.0, 2.0, 3.0)]
    return gated + capped


def l2_arms(rows: list[dict], arms: dict[str, Arm]) -> list[Arm]:
    """The L1 winner's form and the best other form, at their best L1 parameters, on kb-v6, kb-v8, kb-v7."""
    winner = dev_search.select(rows, arms)
    ranked = form_scores(rows, arms)
    picks: list[Arm] = []
    if winner is not None:
        picks.append(arms[winner["arm_id"]])
    for form, best in ranked:
        if len(picks) == 2:
            break
        if form not in {p.config.neg_form for p in picks}:
            picks.append(arms[best["arm_id"]])
    out = []
    for p in picks:
        for kb in L2_KBS:
            c = replace(p.config, kb_id=kb)
            out.append(Arm(f"L2:{p.arm_id.removeprefix('L1:')}:{kb}", "L2", c, f"from {p.arm_id}"))
    return out


def l3_arms(base: RerankConfig) -> list[Arm]:
    out = [Arm("L3:base", "ref", base, "L1+L2 winner, no L3 feature")]
    for group, names in L3_GROUPS.items():
        for w in L3_WEIGHTS:
            weights = {**base.weights, **dict.fromkeys(names, w)}
            out.append(Arm(f"L3:{group}:w{w:g}", "L3", replace(base, weights=weights)))
    return out
